contract InvMutTest
{
    C c;

    constructor(C _c) { c = _c; }

    fallback() external payable {}
    receive() external payable {}

    function test(uint amount) public
    {
        require(amount > 0);
        require(address(this).balance >= amount);

        c.SetMinSum(0);
        c.SetLogFile(address(this));
        c.Deposit{value: amount}();

        uint balBefore = c.balances(address(this));
        uint ethBefore = address(this).balance;

        c.Collect(amount);

        assert(c.balances(address(this)) == balBefore - amount
               && address(this).balance >= ethBefore + amount);
    }
}

